use verus::prelude::*;

verus! {

    // Given a non-empty vector of usize, returns its maximum element.
    // Requires:
    //   lst.len() > 0
    // Ensures:
    //   1) For every index i in bounds, lst[i] <= result.
    //   2) There exists some index i in bounds with lst[i] == result.
    pub fn max_of_list(lst: &Vec<usize>) -> usize
        requires
            lst.len() > 0,
        ensures
            forall |i: nat| i < lst.len() ==> lst[i] <= result,
        ensures
            exists |i: nat| i < lst.len() && lst[i] == result
    {
        // We scan from left to right, maintaining:
        //   1) `current_max` is equal to some element in lst[0..i).
        //   2) All elements in lst[0..i) are <= `current_max`.
        // Start with i = 1, current_max = lst[0].
        let mut i: nat = 1;
        let mut current_max: usize = lst[0];

        while i < lst.len()
            invariant
                i <= lst.len(),
                // All seen elements up to index i are <= current_max.
                forall |j: nat| j < i ==> lst[j] <= current_max,
                // current_max equals one of the seen elements.
                exists |j: nat| j < i && lst[j] == current_max,
            decreases
                lst.len() - i
        {
            let v = lst[i];
            if v > current_max {
                current_max = v;
            }
            i += 1;
        }

        // At this point i == lst.len(), so the invariants witness:
        // 1) forall j < lst.len(): lst[j] <= current_max
        // 2) exists j < lst.len(): lst[j] == current_max
        current_max
    }

}